function() {
  var h = window.location.hostname || '';
  var s = window.location.search || '';
  var isDebug = ({{Debug Mode}} === true || s.indexOf('debug_mode=1') !== -1 || s.indexOf('gtm_debug') !== -1);
  if (isDebug) return 'false';
  if (h !== 'nihongo.oscarchair.jp') return 'true';
  if (s.indexOf('preview=true') !== -1) return 'true';
  if (document.body && (document.body.classList.contains('logged-in') || document.body.classList.contains('admin-bar'))) {
    return 'true';
  }
  return 'false';
}

function() {
  var p = window.location.pathname || '/';
  var s = window.location.search || '';
  var b = document.body;
  if (/[?&]s=/.test(s) || (b && b.classList.contains('error404'))) {
    return 'サイト内検索結果・404';
  }
  if (p === '/') return 'TOP';
  if (p.indexOf('/articles') === 0) return '学習ノート一覧（総合フィルタ）';
  if (p.indexOf('/category/') === 0 || p.indexOf('/tag/') === 0) return 'カテゴリー・タグ一覧';
  if (p.indexOf('/manga') === 0 || (b && b.classList.contains('c-entry--manga'))) return '4コマ漫画';
  if (/^\/(about|privacy-policy|terms|sitemap)\/?$/.test(p)) return '運営案内・法務・サイトマップ';
  if (b && b.classList.contains('is-single-post')) {
    if (b.classList.contains('category-comparing') || p.indexOf('/japanese-comparing-') === 0) return '記事詳細：くらべてみました';
    if (b.classList.contains('category-kotoba-no-aya') || p.indexOf('/kotoba-no-aya-') === 0) return '記事詳細：ことばのあや';
    if (b.classList.contains('category-culture-shock') || p.indexOf('/culture-shock-') === 0) return '記事詳細：カルチャーショック';
    if (b.classList.contains('category-street-japanese') || p.indexOf('/street-japanese-') === 0) return '記事詳細：街角サバイバル';
    return '記事詳細：その他';
  }
  return 'その他';
}

function() {
  var badge = document.querySelector('.c-entry__meta .c-badge--jlpt');
  if (!badge) return '未設定';
  var txt = (badge.innerText || badge.textContent || '').replace(/[^A-Za-z0-9\s\-〜~]/g, '').replace(/\s+/g, ' ').trim();
  return txt || '未設定';
}

function() {
  var u = {{Click URL}} || '';
  if (!u) return 'false';
  try {
    var parsed = new URL(u, window.location.origin);
    var host = (parsed.hostname || '').toLowerCase();
    return (host === 'oscarchair.jp' || host === 'www.oscarchair.jp') ? 'true' : 'false';
  } catch (e) {
    return /^https?:\/\/(www\.)?oscarchair\.jp(\/|$)/i.test(u) ? 'true' : 'false';
  }
}

function() {
  if (document.body && document.body.classList.contains('is-ruby-hidden')) {
    return 'OFF';
  }
  if (document.documentElement && document.documentElement.classList.contains('is-ruby-hidden')) {
    return 'OFF';
  }
  return 'ON';
}

function() {
  var el = {{Click Element}};
  if (el && el.closest && el.closest('#ruby-sticky-toggle, .c-ruby-toggle--sticky')) {
    return 'sticky_float';
  }
  return 'entry_header';
}

function() {
  var el = {{Click Element}};
  if (el && el.closest) {
    var tab = el.closest('.c-sort-tab');
    if (tab && tab.getAttribute('data-sort')) {
      return tab.getAttribute('data-sort');
    }
  }
  var u = {{Click URL}} || '';
  return u.indexOf('sort=views') !== -1 ? 'views' : 'latest';
}

function() {
  var el = {{Click Element}};
  if (el && el.closest && el.closest('.c-jlpt-filter-btn, .c-filter-row--jlpt')) {
    return 'jlpt_level';
  }
  return 'series_category';
}

function() {
  var el = {{Click Element}};
  if (el && el.closest) {
    var card = el.closest('article.c-card');
    if (card) {
      var titleEl = card.querySelector('.c-card__title-link, .c-card__title');
      if (titleEl) {
        return (titleEl.innerText || titleEl.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 100);
      }
    }
  }
  return ({{Click Text}} || '').replace(/\s+/g, ' ').trim().slice(0, 100);
}

function() {
  var el = {{Click Element}};
  if (!el || !el.closest) return 'archive_list';
  if (el.closest('.c-related-posts')) return 'related_posts';
  if (el.closest('#latest-posts, .c-latest-posts')) return 'top_latest';
  if (el.closest('.c-error-recommendations')) return '404_recommend';
  return 'archive_list';
}

function() {
  var el = {{Click Element}};
  if (!el || !el.closest) return 'other_nav';
  if (el.closest('.c-blog-card')) return 'inline_blog_card';
  if (el.closest('.c-series-list, .c-series-box')) return 'series_backnumber';
  if (el.closest('.c-post-connected-manga, .c-manga-connected-post')) return 'manga_crosslink';
  if (el.closest('.c-post-nav')) return 'prev_next_post';
  if (el.closest('.c-badge--category, .c-badge--tag')) return 'taxonomy_badge';
  if (el.closest('.c-breadcrumb')) return 'breadcrumb';
  if (el.closest('.c-pagination')) return 'pagination';
  return 'other_nav';
}

function() {
  var form = {{Form Element}};
  var input = form && form.querySelector ? form.querySelector('input[name="s"]') : document.querySelector('input[name="s"]');
  if (input && input.value) {
    return input.value.replace(/\s+/g, ' ').trim().slice(0, 100);
  }
  return '';
}

function() {
  var cid = {{Click ID}} || '';
  if (cid) return cid;
  var cls = {{Click Classes}} || '';
  if (cls.indexOf('c-hero') !== -1) return 'hero';
  return cls.split(' ')[0] || 'top_section';
}
